def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z][1-9][0-9]?|SUM|MIN|MAX|IF|<>|<=|>=|[()+*/,:=<>-]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse(text):
        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for match in token_pattern.finditer(text):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("number", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                operators.append(token)
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()

                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append((function, arguments))

                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()

        return nodes[0]

    def expanded_arguments(arguments):
        for argument in arguments:
            if argument[0] != ":":
                yield argument
                continue

            first = argument[1][1]
            last = argument[2][1]
            c1, c2 = sorted((ord(first[0]), ord(last[0])))
            r1, r2 = sorted((int(first[1:]), int(last[1:])))

            for row in range(r1, r2 + 1):
                for column in range(c1, c2 + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    values = {}
    active = set()

    def evaluate_cell(root):
        tasks = [("cell", root)]
        results = []

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    content = cells[name].strip()
                    if not content.startswith("="):
                        value = int(content)
                        values[name] = value
                        results.append(value)
                    else:
                        active.add(name)
                        tasks.append(("finish_cell", name))
                        tasks.append(("evaluate", parse(content[1:])))

            elif action == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    results.append(node[1])
                elif kind == "reference":
                    tasks.append(("cell", node[1]))
                elif kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))
                elif kind == "IF":
                    condition, then_branch, else_branch = node[1]
                    tasks.append(("choose", then_branch, else_branch))
                    tasks.append(("evaluate", condition))
                elif kind in functions:
                    tasks.append((
                        "aggregate_next",
                        kind,
                        expanded_arguments(node[1]),
                        None,
                    ))
                else:
                    tasks.append(("binary_left", kind, node[2]))
                    tasks.append(("evaluate", node[1]))

            elif action == "negate":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif action == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif action == "binary_right":
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        value = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            value = -value
                elif op == "=":
                    value = left == right
                elif op == "<>":
                    value = left != right
                elif op == "<":
                    value = left < right
                elif op == "<=":
                    value = left <= right
                elif op == ">":
                    value = left > right
                else:
                    value = left >= right

                results.append(value)

            elif action == "choose":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("evaluate", branch))

            elif action == "aggregate_next":
                kind, arguments, accumulator = task[1:]
                argument = next(arguments, None)
                if argument is None:
                    results.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append((
                        "aggregate_value", kind, arguments, accumulator
                    ))
                    tasks.append(("evaluate", argument))

            elif action == "aggregate_value":
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                    continue

                kind, arguments, accumulator = task[1:]
                if accumulator is None:
                    accumulator = value
                elif kind == "SUM":
                    accumulator += value
                elif kind == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append((
                    "aggregate_next", kind, arguments, accumulator
                ))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate_cell(name)

    return {name: values[name] for name in cells}
